<script>
// Complete data dictionary for Mouse Feeders
const tabData = {
  "M-FEED": {
    preTitle: "STANDARD",
    title: "M-FEED",
    description: "Mouse food tray. A plastic feeder with a metal insert.",
    imageSrc: "https://inno.myvoladolabs.com/wp-content/uploads/2026/06/M-FEED.png", // Use the main one from the third image
    advantages: [
